"use client";

import { memo, useCallback, useState } from "react";
import { IconCheck, IconChevronDown } from "@tabler/icons-react";
import type { ModelOption } from "../types";
import { cn } from "../utils/cn";
import { Popover } from "./popover";

export type ModelPickerProps = {
  models: ModelOption[];
  value?: string;
  defaultValue?: string;
  onChange?: (modelId: string) => void;
  placeholder?: string;
  className?: string;
};

export const ModelPicker = memo(function ModelPicker({
  models,
  value,
  defaultValue,
  onChange,
  placeholder = "Auto",
  className,
}: ModelPickerProps) {
  const isControlled = value !== undefined;
  const [internalValue, setInternalValue] = useState(defaultValue);
  const activeId = isControlled ? value : internalValue;
  const activeModel = models.find((m) => m.id === activeId) ?? models[0];
  const [open, setOpen] = useState(false);

  const handleSelect = useCallback(
    (id: string) => {
      if (!isControlled) setInternalValue(id);
      onChange?.(id);
      setOpen(false);
    },
    [isControlled, onChange],
  );

  return (
    <Popover
      open={open}
      onOpenChange={setOpen}
      side="top"
      align="start"
      trigger={
        <button
          type="button"
          className={cn(
            "inline-flex h-7 items-center gap-1 rounded-[6px] px-2 text-[12px] leading-4 text-foreground/40 transition-colors hover:bg-foreground/6 cursor-pointer",
            className,
          )}
          aria-label="Select model"
        >
          <span className="font-medium">
            {activeModel?.name ?? placeholder}
          </span>
          {activeModel?.version && (
            <span className="font-normal text-foreground/25">
              {activeModel.version}
            </span>
          )}
          <IconChevronDown className="size-3 text-foreground/40" />
        </button>
      }
    >
      {models.map((model) => {
        const isActive = model.id === activeModel?.id;
        return (
          <button
            key={model.id}
            type="button"
            onClick={() => handleSelect(model.id)}
            className={cn(
              "flex w-full items-center gap-2 rounded-[6px] px-2 py-1.5 text-left text-[12px] leading-4 text-an-foreground transition-colors hover:bg-foreground/6 cursor-pointer",
              isActive && "bg-foreground/6",
            )}
          >
            <span className="flex-1 truncate">
              {model.name}
              {model.version && (
                <span className="ml-1 text-foreground/40">{model.version}</span>
              )}
            </span>
            {isActive && (
              <IconCheck className="size-3.5 shrink-0 text-foreground/60" />
            )}
          </button>
        );
      })}
    </Popover>
  );
});

export type ModelBadgeProps = {
  models: ModelOption[];
  value?: string;
  placeholder?: string;
  className?: string;
};

export const ModelBadge = memo(function ModelBadge({
  models,
  value,
  placeholder = "Auto",
  className,
}: ModelBadgeProps) {
  const activeModel = models.find((m) => m.id === value) ?? models[0];
  return (
    <div
      className={cn(
        "inline-flex h-7 items-center px-2 text-[12px] leading-4 text-foreground/30",
        className,
      )}
    >
      <span className="font-medium">{activeModel?.name ?? placeholder}</span>
      {activeModel?.version && (
        <span className="ml-0.5 font-normal text-foreground/20">
          {activeModel.version}
        </span>
      )}
    </div>
  );
});

import type React from "react";
import type { UIMessage, ChatStatus } from "ai";
import type {
  QuestionAnswer,
  QuestionConfig,
} from "./question/question-prompt";
import type { SuggestionItem } from "./input/suggestions";

export type InputSuggestions =
  | SuggestionItem[]
  | {
      items: SuggestionItem[];
      className?: string;
      itemClassName?: string;
    };

/** Theme JSON generated by the playground */
export type ChatTheme = {
  theme: Record<string, string>;
  light: Record<string, string>;
  dark: Record<string, string>;
};

/** Per-element CSS class overrides */
export type ChatClassNames = {
  root: string;
  userMessage: string;
  inputBar: string;
};

/** Props for createAgentChat() */
export type CreateAgentChatOptions = {
  agent: string;
  /** Provide either tokenUrl (simple) or getToken (full control) */
  tokenUrl?: string;
  getToken?: () => Promise<string>;
  apiUrl?: string;
  /**
   * Sandbox ID — identifies the persistent sandbox environment.
   *
   * Each unique `sandboxId` maps to its own sandbox (isolated VM with persistent filesystem).
   * Requests with the same `sandboxId` share the same sandbox — files, git repos,
   * and session history persist across messages.
   *
   * If omitted, the relay creates a new sandbox per request.
   *
   * @example
   * // Per-user sandbox
   * createAgentChat({ agent: "my-agent", tokenUrl: "/api/an/token", sandboxId: `user-${userId}` })
   *
   * // Continue existing sandbox
   * createAgentChat({ agent: "my-agent", tokenUrl: "/api/an/token", sandboxId: sandbox.id })
   */
  sandboxId?: string;
  /**
   * Thread ID — identifies a specific conversation thread within the sandbox.
   * Requires `sandboxId` to be set. If omitted with `sandboxId`, creates a new thread.
   */
  threadId?: string;
  onFinish?: () => void;
  onError?: (error: Error) => void;
};

/** Props passed to custom tool renderer components */
export type CustomToolRendererProps = {
  name: string;
  input: Record<string, unknown>;
  output: unknown | undefined;
  status: "pending" | "streaming" | "success" | "error";
};

/** Component slot overrides */
export type ChatSlots = {
  InputBar: React.ComponentType<{
    onSend: (message: { role: "user"; content: string }) => void;
    status: ChatStatus;
    onStop: () => void;
    [key: string]: unknown;
  }>;
  UserMessage: React.ComponentType<{
    message: UIMessage;
    className?: string;
  }>;
  ToolRenderer: React.ComponentType<{
    part: {
      type: string;
      toolCallId?: string;
      state?: string;
      input?: unknown;
      output?: unknown;
      result?: unknown;
    };
    nestedTools?: {
      type: string;
      toolCallId?: string;
      state?: string;
      input?: unknown;
      output?: unknown;
      result?: unknown;
    }[];
    chatStatus?: string;
    toolRenderers?: Record<
      string,
      React.ComponentType<CustomToolRendererProps>
    >;
  }>;
};

/** A model option for the model selector */
export type ModelOption = {
  id: string;
  name: string;
  version?: string;
};

/** Props for the <AgentChat> drop-in component */
export type AgentChatProps = {
  messages: UIMessage[];
  onSend: (message: { role: "user"; content: string }) => void;
  status: ChatStatus;
  onStop: () => void;
  error?: Error;

  classNames?: Partial<ChatClassNames>;
  slots?: Partial<ChatSlots>;
  toolRenderers?: Record<string, React.ComponentType<CustomToolRendererProps>>;

  /** Attachment configuration */
  attachments?: {
    onAttach?: () => void;
    images?: { id: string; filename: string; url: string; size?: number }[];
    files?: { id: string; filename: string; size?: number }[];
    onRemoveImage?: (id: string) => void;
    onRemoveFile?: (id: string) => void;
    onPaste?: (e: React.ClipboardEvent) => void;
    isDragOver?: boolean;
  };

  /** Show copy toolbar on text turns */
  showCopyToolbar?: boolean;

  /**
   * Where to position the scroll container on initial mount.
   * - "bottom" (default): classic chat behavior, pinned to the latest message.
   * - "top": start from the top of the conversation — useful for static demos
   *   or read-only transcripts where the user should read top-to-bottom.
   */
  initialScrollBehavior?: "bottom" | "top";

  /**
   * When true (default) clicking an attached image opens a fullscreen
   * lightbox preview. Set to false to render images as plain thumbnails
   * (no click handler, no portal). Applies to both staged input attachments
   * and images inside user messages.
   */
  enableImagePreview?: boolean;

  suggestions?: InputSuggestions;

  emptyStatePosition?: "default" | "center";
  emptySuggestionsPlacement?: "input" | "empty" | "both";
  emptySuggestionsPosition?: "top" | "bottom";

  questionTool?: {
    submitLabel?: string;
    skipLabel?: string;
    allowSkip?: boolean;
    onAnswer?: (payload: {
      toolCallId?: string;
      question: QuestionConfig;
      answer: QuestionAnswer;
    }) => void;
  };

  className?: string;
  style?: React.CSSProperties;
};

// Legacy type aliases kept for compatibility.
export type AnTheme = ChatTheme;
export type AnClassNames = ChatClassNames;
export type AnSlots = ChatSlots;
export type CreateAnChatOptions = CreateAgentChatOptions;
export type AnModelOption = ModelOption;
export type AnAgentChatProps = AgentChatProps;

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import type { ReactNode } from "react";
import { Popover as BasePopover } from "@base-ui/react/popover";
import { cn } from "../utils/cn";

export type PopoverSide = "top" | "bottom" | "left" | "right";
export type PopoverAlign = "start" | "center" | "end";

export type PopoverProps = {
  trigger: ReactNode;
  children: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  side?: PopoverSide;
  align?: PopoverAlign;
  sideOffset?: number;
  className?: string;
};

export function Popover({
  trigger,
  children,
  open,
  defaultOpen,
  onOpenChange,
  side = "top",
  align = "start",
  sideOffset = 6,
  className,
}: PopoverProps) {
  return (
    <BasePopover.Root
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange ? (next) => onOpenChange(next) : undefined}
    >
      <BasePopover.Trigger
        render={(props) => (
          <span {...props} className="inline-flex">
            {trigger}
          </span>
        )}
      />
      <BasePopover.Portal>
        <BasePopover.Positioner side={side} align={align} sideOffset={sideOffset}>
          <BasePopover.Popup
            className={cn(
              "min-w-[180px] rounded-[10px] border border-an-border-color bg-an-background p-1 shadow-lg outline-none",
              "text-an-foreground",
              className,
            )}
          >
            {children}
          </BasePopover.Popup>
        </BasePopover.Positioner>
      </BasePopover.Portal>
    </BasePopover.Root>
  );
}

import { useEffect, useMemo, useState } from "react";
import { cn } from "../utils/cn";

export type QuestionOption = {
  id: string;
  label: string;
  description?: string;
};

export type QuestionConfig = {
  kind: "single" | "multi" | "text";
  title: string;
  description?: string;
  options?: QuestionOption[];
  allowCustom?: boolean;
  customLabel?: string;
  customPlaceholder?: string;
  minSelections?: number;
  maxSelections?: number;
  placeholder?: string;
};

export type QuestionAnswer = {
  kind: "single" | "multi" | "text" | "skip";
  selectedIds?: string[];
  text?: string;
};

const QUESTION_CUSTOM_ID = "__custom__";

function optionBadge(idx: number) {
  return String.fromCharCode(65 + idx);
}

export type QuestionPromptProps = {
  questions: QuestionConfig[];
  questionIndex?: number;
  totalQuestions?: number;
  onPreviousQuestion?: () => void;
  onNextQuestion?: () => void;
  initialAnswer?: QuestionAnswer;
  /** Label for the primary action on the LAST question (default "Send"). */
  submitLabel?: string;
  /** Label for the primary action when there are more questions ahead
   *  (default "Next"). The host (e.g. QuestionTool) is expected to advance
   *  to the next question after onSubmit fires. */
  nextLabel?: string;
  skipLabel?: string;
  allowSkip?: boolean;
  onSubmit: (answer: QuestionAnswer) => void;
  onSkip?: () => void;
  className?: string;
};

export function QuestionPrompt({
  questions,
  questionIndex = 1,
  totalQuestions,
  onPreviousQuestion,
  onNextQuestion,
  submitLabel = "Send",
  nextLabel = "Next",
  skipLabel = "Skip",
  allowSkip = true,
  initialAnswer,
  onSubmit,
  onSkip,
  className,
}: QuestionPromptProps) {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [customText, setCustomText] = useState("");
  const [textValue, setTextValue] = useState("");
  const resolvedTotal = totalQuestions ?? questions.length;
  const clampedIndex = Math.max(1, Math.min(questionIndex, resolvedTotal));
  const activeQuestion = questions[clampedIndex - 1];
  const customEnabled = activeQuestion?.allowCustom ?? false;
  const showNav =
    resolvedTotal > 1 && (!!onPreviousQuestion || !!onNextQuestion);
  const canGoPrev = clampedIndex > 1;
  const canGoNext = clampedIndex < resolvedTotal;
  const isLastQuestion = clampedIndex >= resolvedTotal;
  const primaryLabel = isLastQuestion ? submitLabel : nextLabel;

  useEffect(() => {
    if (!initialAnswer || initialAnswer.kind === "skip") {
      setSelectedIds([]);
      setCustomText("");
      setTextValue("");
      return;
    }

    if (activeQuestion?.kind === "text") {
      setSelectedIds([]);
      setCustomText("");
      setTextValue(initialAnswer.text ?? "");
      return;
    }

    const nextSelected = new Set(initialAnswer.selectedIds ?? []);
    const nextCustomText = initialAnswer.text ?? "";
    if (customEnabled && nextCustomText.trim().length > 0) {
      nextSelected.add(QUESTION_CUSTOM_ID);
    }
    setSelectedIds(Array.from(nextSelected));
    setCustomText(nextCustomText);
    setTextValue("");
  }, [
    activeQuestion?.kind,
    clampedIndex,
    customEnabled,
    initialAnswer?.kind,
    initialAnswer?.text,
    initialAnswer?.selectedIds?.join("|"),
  ]);

  const canSubmit = useMemo(() => {
    if (activeQuestion?.kind === "text") return textValue.trim().length > 0;

    const selectedNonCustom = selectedIds.filter(
      (id) => id !== QUESTION_CUSTOM_ID,
    ).length;
    const hasCustomText = customText.trim().length > 0;
    const total = selectedNonCustom + (hasCustomText ? 1 : 0);

    if (activeQuestion?.kind === "single") {
      return total === 1;
    }

    const min = activeQuestion?.minSelections ?? 1;
    const max = activeQuestion?.maxSelections;
    if (total < min) return false;
    if (typeof max === "number" && total > max) return false;
    return total > 0;
  }, [
    activeQuestion?.kind,
    activeQuestion?.minSelections,
    activeQuestion?.maxSelections,
    selectedIds,
    customText,
    textValue,
  ]);

  const toggleMulti = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id],
    );
  };

  const handleSingleSelect = (id: string) => {
    setSelectedIds([id]);
  };

  const handleCustomTextChange = (nextValue: string) => {
    setCustomText(nextValue);
    if (!activeQuestion) return;
    if (activeQuestion.kind === "single") {
      setSelectedIds(nextValue.trim().length > 0 ? [QUESTION_CUSTOM_ID] : []);
      return;
    }
    setSelectedIds((prev) => {
      const hasCustom = prev.includes(QUESTION_CUSTOM_ID);
      if (nextValue.trim().length > 0 && !hasCustom) {
        return [...prev, QUESTION_CUSTOM_ID];
      }
      if (nextValue.trim().length === 0 && hasCustom) {
        return prev.filter((id) => id !== QUESTION_CUSTOM_ID);
      }
      return prev;
    });
  };

  const handleSubmit = () => {
    if (!canSubmit || !activeQuestion) return;
    if (activeQuestion.kind === "text") {
      onSubmit({ kind: "text", text: textValue.trim() });
      return;
    }

    const selectedNonCustom = selectedIds.filter(
      (id) => id !== QUESTION_CUSTOM_ID,
    );
    const answerText = customText.trim() || undefined;
    onSubmit({
      kind: activeQuestion.kind,
      selectedIds: selectedNonCustom,
      text: answerText || undefined,
    });
  };

  const handleSkip = () => {
    onSkip?.();
    onSubmit({ kind: "skip" });
  };

  if (!activeQuestion) return null;

  return (
    <div className={cn("px-3 py-2 space-y-2 bg-background", className)}>
      <div
        className="flex items-center justify-between gap-px"
        data-total-questions={resolvedTotal}
      >
        <div className="flex items-center gap-2 text-sm text-an-tool-color">
          <span className="h-5 min-w-5 px-1 rounded-[4px] inline-flex items-center justify-center text-sm font-medium text-an-tool-color-muted">
            {clampedIndex}
          </span>
          <span>{activeQuestion.title}</span>
        </div>
      </div>

      {activeQuestion.kind !== "text" &&
        (activeQuestion.options?.length ?? 0) > 0 && (
          <div className="space-y-px">
            {activeQuestion.options!.map((option, idx) => {
              const checked = selectedIds.includes(option.id);
              return (
                <button
                  key={option.id}
                  type="button"
                  onClick={() => {
                    if (activeQuestion.kind === "single") {
                      handleSingleSelect(option.id);
                      if (customEnabled) setCustomText("");
                    } else {
                      toggleMulti(option.id);
                    }
                  }}
                  className="w-full text-left rounded-md px-2 py-1.5 flex items-center gap-2 hover:bg-an-background-secondary -mx-2"
                >
                  <span
                    className={cn(
                      "h-5 min-w-5 px-1 rounded-[4px] inline-flex items-center justify-center text-sm font-medium border",
                      checked
                        ? "bg-an-primary-color text-an-send-button-color border-an-primary-color"
                        : "bg-transparent text-an-tool-color-muted border-border",
                    )}
                  >
                    {optionBadge(idx)}
                  </span>
                  <span className="text-sm text-an-tool-color">
                    {option.label}
                    {option.description && (
                      <span className="text-an-tool-color-muted">
                        {" "}
                        {option.description}
                      </span>
                    )}
                  </span>
                </button>
              );
            })}

            {customEnabled && (
              <div className="pt-1 flex items-center gap-2">
                <span
                  className={cn(
                    "h-5 min-w-5 px-1 rounded-[4px] inline-flex items-center justify-center text-sm font-medium border",
                    selectedIds.includes(QUESTION_CUSTOM_ID)
                      ? "bg-an-primary-color text-an-send-button-color border-an-primary-color"
                      : "bg-transparent text-an-tool-color-muted border-border",
                  )}
                >
                  {optionBadge(activeQuestion.options!.length)}
                </span>
                <input
                  value={customText}
                  onChange={(event) =>
                    handleCustomTextChange(event.target.value)
                  }
                  placeholder={
                    activeQuestion.customPlaceholder ?? "Type your answer"
                  }
                  className="w-full h-7 rounded-md border border-border bg-background px-2 text-sm text-an-tool-color"
                />
              </div>
            )}
          </div>
        )}

      {activeQuestion.kind === "text" && (
        <textarea
          value={textValue}
          onChange={(event) => setTextValue(event.target.value)}
          placeholder={activeQuestion.placeholder ?? "Type your answer"}
          rows={3}
          className="w-full rounded-md border border-border bg-background px-2 py-1.5 text-sm text-an-tool-color resize-y"
        />
      )}

      <div
        className={cn(
          "flex items-center gap-1.5",
          showNav ? "justify-between" : "justify-end",
        )}
      >
        {showNav && (
          <div className="flex items-center gap-1.5">
            {onPreviousQuestion && (
              <button
                type="button"
                onClick={onPreviousQuestion}
                disabled={!canGoPrev}
                className="h-6 px-2 rounded-[4px] text-sm text-muted-foreground hover:text-an-tool-color disabled:opacity-60"
              >
                Previous
              </button>
            )}
            {onNextQuestion && (
              <button
                type="button"
                onClick={onNextQuestion}
                disabled={!canGoNext}
                className="h-6 px-2 rounded-[4px] text-sm text-muted-foreground hover:text-an-tool-color disabled:opacity-60"
              >
                Next
              </button>
            )}
          </div>
        )}
        <div className="flex items-center justify-end gap-1.5">
          {allowSkip && (
            <button
              type="button"
              onClick={handleSkip}
              className="h-6 px-2 rounded-[4px] text-sm text-muted-foreground hover:text-an-tool-color hover:bg-muted/50 active:scale-[0.98] transition-[background-color,color,transform] duration-150"
            >
              {skipLabel}
            </button>
          )}
          <button
            type="button"
            onClick={handleSubmit}
            disabled={!canSubmit}
            className="h-6 px-2.5 rounded-[4px] text-sm font-medium bg-an-primary-color text-an-send-button-color hover:bg-an-primary-color/90 active:scale-[0.98] transition-[background-color,transform] duration-150 disabled:opacity-60 disabled:hover:bg-an-primary-color disabled:active:scale-100"
          >
            {primaryLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

/* Agent Elements tokens + utilities */

/*
 * AN Agent Chat - CSS Custom Properties
 * These are the default values. Override by redefining these vars in your app CSS.
 */
:root {
  /* Geometry — all radii derive from --an-border-radius */
  --an-border-radius: 16px;
  --an-message-border-radius: var(--an-border-radius);
  --an-input-border-radius: var(--an-border-radius);
  --an-tool-border-radius: 10px;
  --an-message-radius-inner-offset: 4px;
  --an-max-width: 420px;

  /* Colors - Light mode defaults */
  --an-background: #ffffff;
  --an-background-secondary: #f0f0f0;
  --an-background-tertiary: #f8f8f8;
  --an-foreground: #1a1a1a;
  --an-foreground-muted: #737373;
  --an-foreground-subtle: #a3a3a3;
  --an-border-color: #e4e4e7;
  --an-primary-color: #3b82f6;

  /* User Messages */
  --an-user-message-bg: #f5f5f5;
  --an-user-message-text: #1a1a1a;

  /* Input */
  --an-input-background: #ffffff;
  --an-input-border-color: #e4e4e7;
  --an-input-color: #1a1a1a;
  --an-input-placeholder-color: #a3a3a3;
  --an-input-focus-outline: transparent;
  --an-context-padding: 10px;

  /* Send/Stop Buttons */
  --an-send-button-bg: #3b82f6;
  --an-send-button-color: #ffffff;

  /* Tools */
  --an-tool-background: #f5f5f5;
  --an-tool-border-color: #e4e4e7;
  --an-tool-color: #1a1a1a;
  --an-tool-color-muted: #737373;

  /* Code */
  --an-code-background: #1e1e1e;
  --an-code-color: #d4d4d4;

  /* Diff colors */
  --an-diff-added-bg: rgba(34, 197, 94, 0.1);
  --an-diff-added-border: rgba(34, 197, 94, 0.5);
  --an-diff-added-text: #15803d;
  --an-diff-removed-bg: rgba(239, 68, 68, 0.1);
  --an-diff-removed-border: rgba(239, 68, 68, 0.5);
  --an-diff-removed-text: #dc2626;
}

/* Dark mode defaults */
.dark {
  --an-background: #0a0a0a;
  --an-background-secondary: #242424;
  --an-background-tertiary: #141414;
  --an-foreground: #fafafa;
  --an-foreground-muted: #8c8c8c;
  --an-foreground-subtle: #71717a;
  --an-border-color: #2a2a2a;
  --an-primary-color: #60a5fa;

  --an-user-message-bg: #1a1a1a;
  --an-user-message-text: #fafafa;

  --an-input-background: #0a0a0a;
  --an-input-border-color: #2a2a2a;
  --an-input-color: #fafafa;
  --an-input-placeholder-color: #71717a;
  --an-input-focus-outline: transparent;
  --an-context-padding: 12px;

  --an-send-button-bg: #60a5fa;
  /* Dark mode uses a lighter primary (#60a5fa) — pair it with black text so
     labels like "Approve" / send-arrow have proper contrast instead of
     low-contrast white-on-light-blue. */
  --an-send-button-color: #0a0a0a;

  --an-tool-background: #141414;
  --an-tool-border-color: #2a2a2a;
  --an-tool-color: #fafafa;
  --an-tool-color-muted: #8c8c8c;

  --an-code-background: #0a0a0a;
  --an-code-color: #d4d4d4;

  --an-diff-added-bg: rgba(34, 197, 94, 0.15);
  --an-diff-added-border: rgba(34, 197, 94, 0.4);
  --an-diff-added-text: #4ade80;
  --an-diff-removed-bg: rgba(239, 68, 68, 0.15);
  --an-diff-removed-border: rgba(239, 68, 68, 0.4);
  --an-diff-removed-text: #f87171;
}

@theme inline {
  --color-an-background: var(--an-background);
  --color-an-background-secondary: var(--an-background-secondary);
  --color-an-background-tertiary: var(--an-background-tertiary);
  --color-an-foreground: var(--an-foreground);
  --color-an-foreground-muted: var(--an-foreground-muted);
  --color-an-foreground-subtle: var(--an-foreground-subtle);
  --color-an-border-color: var(--an-border-color);
  --color-an-primary-color: var(--an-primary-color);
  --color-an-user-message-bg: var(--an-user-message-bg);
  --color-an-user-message-text: var(--an-user-message-text);
  --color-an-input-background: var(--an-input-background);
  --color-an-input-border-color: var(--an-input-border-color);
  --color-an-input-color: var(--an-input-color);
  --color-an-input-placeholder-color: var(--an-input-placeholder-color);
  --color-an-input-focus-outline: var(--an-input-focus-outline);
  --color-an-send-button-bg: var(--an-send-button-bg);
  --color-an-send-button-color: var(--an-send-button-color);
  --color-an-tool-background: var(--an-tool-background);
  --color-an-tool-border-color: var(--an-tool-border-color);
  --color-an-tool-color: var(--an-tool-color);
  --color-an-tool-color-muted: var(--an-tool-color-muted);
  --color-an-code-background: var(--an-code-background);
  --color-an-code-color: var(--an-code-color);
  --color-an-diff-added-bg: var(--an-diff-added-bg);
  --color-an-diff-added-border: var(--an-diff-added-border);
  --color-an-diff-added-text: var(--an-diff-added-text);
  --color-an-diff-removed-bg: var(--an-diff-removed-bg);
  --color-an-diff-removed-border: var(--an-diff-removed-border);
  --color-an-diff-removed-text: var(--an-diff-removed-text);
  --radius-an-message: var(--an-message-border-radius);
  --radius-an-message-inner: calc(
    var(--an-message-border-radius) - var(--an-message-radius-inner-offset)
  );
  --radius-an-input-border-radius: var(--an-input-border-radius);
  --radius-an-tool-border-radius: var(--an-tool-border-radius);
  --spacing-an-context-padding: var(--an-context-padding);
  --max-width-an: var(--an-max-width);
  --spacing-an-user-message-x: 14px;
  --spacing-an-user-message-y: 10px;
}

/* TextShimmer animation */
@keyframes an-shimmer {
  from {
    background-position: 100% center;
  }
  to {
    background-position: 0% center;
  }
}

@keyframes an-blink {
  50% {
    opacity: 0;
  }
}

@keyframes loading-dots {
  0%,
  100% {
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
}

@keyframes an-ellipsis {
  0% {
    width: 0;
  }
  33% {
    width: 0.33em;
  }
  66% {
    width: 0.66em;
  }
  100% {
    width: 1em;
  }
}

.an-text-shimmer {
  display: inline-block;
  background-size: 250% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  background-image: linear-gradient(
    90deg,
    var(--an-foreground-subtle, #a3a3a3) 0%,
    var(--an-foreground-subtle, #a3a3a3) 40%,
    var(--an-foreground-muted, #737373) 50%,
    var(--an-foreground-subtle, #a3a3a3) 60%,
    var(--an-foreground-subtle, #a3a3a3) 100%
  );
  background-repeat: no-repeat;
}

.an-text-shimmer--active {
  animation: an-shimmer var(--an-shimmer-duration, 2s) linear infinite;
}

.an-ellipsis {
  display: inline-block;
  overflow: hidden;
  width: 0;
  vertical-align: bottom;
  animation: an-ellipsis 1.2s steps(1, end) infinite;
}

.an-markdown pre code {
  counter-reset: none !important;
}

.an-markdown pre code > span::before {
  content: none !important;
  display: none !important;
}

.an-markdown pre code > span {
  padding-left: 0 !important;
}

/* Diff */
.an-edit-diff,
.an-edit-diff pre,
.an-edit-diff code {
  font-size: 12px;
}

.dark .an-edit-tool-card {
  background-color: #000;
}

[data-theme="dark"] .an-edit-tool-card {
  background-color: #000;
}

.dark .an-edit-tool-card .an-edit-diff,
.dark .an-edit-tool-card .an-edit-diff pre,
.dark .an-edit-tool-card .an-edit-diff code {
  background-color: #000 !important;
}

[data-theme="dark"] .an-edit-tool-card .an-edit-diff,
[data-theme="dark"] .an-edit-tool-card .an-edit-diff pre,
[data-theme="dark"] .an-edit-tool-card .an-edit-diff code {
  background-color: #000 !important;
}

/* Markdown Code Block */
.an-markdown [data-streamdown="code-block"] {
  padding: 0;
  border: 1px solid var(--an-border-color);
  border-radius: var(--an-tool-border-radius);
  background: transparent;
  gap: 0;
}

.an-markdown [data-streamdown="code-block-header"] {
  padding: 0px 10px 0px 8px;
  height: auto;
  font-size: 12px;
  height: 28px;
  background: transparent;
  border-bottom: 1px solid var(--color-an-tool-border-color);
  background-color: var(--an-tool-background);
  position: relative;
}

.an-markdown div:has(> [data-streamdown="code-block-actions"]) {
  position: absolute;
  height: auto;
  margin: 0;
  top: 0;
  right: 0;
  height: 28px;
  padding-right: 8px;
}

.an-markdown [data-streamdown="code-block-actions"] {
  background: transparent;
  border: none;
  backdrop-filter: none;
  padding: 0;
}

.an-markdown [data-streamdown="code-block-actions"] button > svg {
  width: 14px;
  height: 14px;
}

.an-markdown [data-streamdown="code-block-body"] {
  margin: 0;
  padding-top: 8px;
  padding-bottom: 8px;
  background: transparent;
  border: transparent;
  overflow-x: auto;
}

.an-markdown [data-streamdown="code-block"] pre,
.an-markdown [data-streamdown="code-block"] code {
  font-size: 12px;
  background: transparent;
}
